CREATE TABLE users (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE products (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, brand VARCHAR(80) NOT NULL, pack_size VARCHAR(40) NOT NULL, category VARCHAR(40) NOT NULL, image_url VARCHAR(255) NOT NULL, mrp BIGINT NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE stores (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, type VARCHAR(20) NOT NULL, address VARCHAR(250) NOT NULL, localities VARCHAR(200) NOT NULL, fee BIGINT NOT NULL, delivery_minutes INT NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE inventory (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, store_id BIGINT NOT NULL, product_id BIGINT NOT NULL, stock INT NOT NULL, regular_price BIGINT NOT NULL, offer_price BIGINT, offer_text VARCHAR(160), offer_start DATETIME(6), offer_end DATETIME(6), updated_at DATETIME(6) NOT NULL, UNIQUE(store_id,product_id), FOREIGN KEY(store_id) REFERENCES stores(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE shopping_lists (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, locality VARCHAR(80) NOT NULL, budget BIGINT, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE list_items (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, list_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, UNIQUE(list_id,product_id), FOREIGN KEY(list_id) REFERENCES shopping_lists(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE saved_plans (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, locality VARCHAR(80) NOT NULL, created_at DATETIME(6) NOT NULL, snapshot LONGTEXT NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE reviews (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, rating INT NOT NULL, comment VARCHAR(1000) NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE INDEX reviews_target ON reviews(target_type,target_id);
CREATE INDEX plans_owner ON saved_plans(owner_id,created_at);
